		[61344] = { -- Chronicler of the Haranir
			"Title: \"Chronicler of the Haranir\"",
			"Discover the 3 lore objects of each of the 7 stories of Legends of the Haranir. They show on the minimap with a magnifying glass. It's done along with achievement 5 (at least 7 weeks).",
			"Laments of Wey'nan: 1 · 2 · 3 · 43.23 37.33 · 41.53 35.85 · 42.30 35.48 · Part 1 at the start, part 2 in stage 2, part 3 in the final stage",
