		[61910] = { -- Mrglgrgl of Grglmrgl
			"Title: Mrglgrgl of Grglmrgl",
			"The 3 stories of King Mrgl-Mrgl: Title: Mrglgrgl of Grglmrgl. They are three old stories and a new one:",
			"Winterfin Retreat (Borean Tundra, WotLK): 13 quests, starts with King Mrgl-Mrgl at the Winterfin Retreat (Borean Tundra coast); it includes escorting Lurgglbr (Escape from the Winterfin Caverns).",
			"Murky Waters (Highmountain, Legion): 6 quests, starts with That Guy in the Costume from Hemet Nesingwary.",
			"The Loa of Murlocs (Zul'Aman): with Old Teo'zan; it also counts toward Sojourner of Zul'Aman.",
			"The two old ones can be done at any level with Timewalking or at max level.",
		},
		[61912] = { -- Anchoring the Defense
			"World event in southwest Voidstorm, every 30 minutes.",
			"Ninety Percent Will Do: Finish the event with the singularity anchor at 90% health or more. It is not account-wide: it counts per character",
			{ "How it works (Stormarion Citadel):", 2405, 26.82, 67.89 },
			"Build phase (5 minutes): you place defenses at fixed spots in the area; each one costs Stormarion Cores (about 10 per defense). Cores come from the event's chests (Victorious Stormarion Cache) and other activities.",
			"3 waves of 3 minutes, with a 30-second break between each. Enemies go straight for the Singularity Anchor, ignore players unless you attack them, and explode on arrival, damaging it.",
			"If the anchor is destroyed, the event ends and there's a 10-minute wait.",
			"For Anchoring the Defense: build one of each (Black Eye · Shock Pylon · Light Barrier · Shadowtrade Mercenary) during the build phase. It's per character, so save about 40 cores. (unconfirmed) It isn't known which build spot gives each defense: check what each spot offers when you click it.",
			"Place the permanent defenses first, because they slow the enemies down in all 3 waves; the consumables only work once.",
			"Place defenses on the enemies' path; at some points they block the way for a while.",
			"Do it when there are lots of people at the event and stay near the anchor killing whatever slips through.",
			"From Xy'dax you can buy support items for the event: Cracked Core (10 cores), Unstable Explosive Device (10) and Illegal Cosmic Emitter (30).",
		},
		[61913] = { -- A Singular Problem
			"World event in southwest Voidstorm, every 30 minutes.",
			"Ninety Percent Will Do: Finish the event with the singularity anchor at 90% health or more. It is not account-wide: it counts per character",
			{ "How it works (Stormarion Citadel):", 2405, 26.82, 67.89 },
			"Build phase (5 minutes): you place defenses at fixed spots in the area; each one costs Stormarion Cores (about 10 per defense). Cores come from the event's chests (Victorious Stormarion Cache) and other activities.",
			"3 waves of 3 minutes, with a 30-second break between each. Enemies go straight for the Singularity Anchor, ignore players unless you attack them, and explode on arrival, damaging it.",
			"If the anchor is destroyed, the event ends and there's a 10-minute wait.",
			"For Anchoring the Defense: build one of each (Black Eye · Shock Pylon · Light Barrier · Shadowtrade Mercenary) during the build phase. It's per character, so save about 40 cores. (unconfirmed) It isn't known which build spot gives each defense: check what each spot offers when you click it.",
			"Place the permanent defenses first, because they slow the enemies down in all 3 waves; the consumables only work once.",
			"Place defenses on the enemies' path; at some points they block the way for a while.",
			"Do it when there are lots of people at the event and stay near the anchor killing whatever slips through.",
			"From Xy'dax you can buy support items for the event: Cracked Core (10 cores), Unstable Explosive Device (10) and Illegal Cosmic Emitter (30).",
		},
		[61916] = { -- Rage of the Ren'dorei
			"Void Elf Demon Hunter",
			"Unlocks the Void Elf Demon Hunter (you need the Void Elf allied race).",
			"Requirement: the story In Search of Darkness in K'aresh (starts with A Common Cause, with Magister Umbric).",
			"It starts with The Pursuit Continues, from Magister Umbric in Dornogal (Messenger Aelor also gives it, and some reports say in Silvermoon). Level 80+; any race can do it.",
			"It's 3 quests helping Leona train as a demon hunter in K'aresh; after finishing Trial of Wrath you get the achievement.",
		},
		[61942] = { -- Heritage of the Haranir
			"Haranir legacy armor",
			"Reach level 50 with a new haranir. Several reports say a boost doesn't count: level it by playing. Reward: two heritage armor sets, Har'alnor and Shul'ka (appearance only, haranir only).",
		},
		[61959] = { -- Focused Target
			"Focused Target (Horde): Kill the 15 Horde champions: \"Don't Die\" Dyona, \"Zappy\" Zikki, Atulash of the Eclipse, Caothun Suntouched, Earthspeaker Ochomu, Giruma Bloodpelt, Buckshot Bazza, Haz'waz the Toxic, Celaryn the Frenzied, Kirok the Charred, Inquisitor Draeleth, Rin'zaka the Galefist, Siatra Spellwing, Taruka Flamehand, Zindroz Darkscale",
			"Focused Target (Alliance): Kill the 15 Alliance champions: Andretta \"Melee\" Nalee, Belanna Brightblaze, Diabolist Inksie, Dawyn the Rabid, Caladon Leechblade, Elder Tae Swiftfoot, Arcanist Aedmos, Falania Nightsoul, Rusty \"Razor\" Maddox, Nella Slagheart, Lessia Giantstrike, Exarch Thoss, Kozar Silverclaw, Theana Trueblade, Ulfrik Stoutarm",
			"The champions appear as enemies of the Training Grounds (unconfirmed). You do the one of the opposite faction.",
			"Note: according to player reports, some champions are bugged and don't appear; it may not be completable until it's fixed.",
			"Tips: training matches are short. Do the map ones together: in each Arathi or Gilneas match take flags, and type /train as soon as you get in.",
		},
