			"Pet: Sootpaw",
			{ "Safe keys: Key 1 (to the right of the ramp of the south tower of Windrunner Village) · Key 2 (next to a broken sin'dorei cart) · Key 3 (next to some rocks near a lantern).", 2395, 37.64, 74.84 },
		},
		[61961] = { -- Runestone Rush
			"How it works: you give Latent Arcana to a runestone until it is charged; that starts an invasion. After several waves the boss appears, and killing the boss is what counts. Only one stone charges at a time. Latent Arcana comes from the weekly rewards of Saltheril's Soiree and from chests around the zone.",
		},
		[62057] = { -- Midnight: The Highest Peaks
			"Midnight: The Highest Peaks (meta)",
			"Place telescopes on the peaks of each zone. You don't need any item: they show on the minimap as a small gray flag; using one plays a short scene and gives +100 reputation with the zone's faction. The meta asks for all 4 zones.",
			{ "Eversong Woods: (unconfirmed) the fifth spot", 2395, 40.4, 10.08 },
			{ "Zul'Aman: (unconfirmed) the fifth spot", 2437, 53.03, 82.04 },
			{ "Harandar", 2413, 53.47, 58.6 },
			{ "Voidstorm", 2405, 41.75, 70.26 },
			"Tip: do the telescopes and the Lorehunter together zone by zone: they're close by and both give renown reputation.",
		},
		[62104] = { -- Midnight Lore Hunter
			"21 lore objects. They show on the minimap with a magnifying glass. Each one gives +250 reputation with the renown faction of its zone.",
		},
		[62105] = { -- Lysikas Would Be Proud
			"Finish the special assignment Special Assignment: Precision Excision (Voidstorm) without missing a single shot. Per character.",
			"Only while the assignment is active; it unlocks with 3 world quests in the zone.",
			"You ride a War Vermis that flies through Stormarion Fortress; you aim at supplies and enemies.",
			"Only shoot with the crosshair over the target and wait for the vermis to settle in each area. If you miss one, it no longer counts that time.",
		},
		[62107] = { -- Mandatory Training
			"Use /train on each map (Gilneas, Arathi, Silvershard). It works at any time, even in the starting area",
		},
		[62109] = { -- Training with Patience
			"Win a match without dying",
		},
		[62110] = { -- Loremaster of Midnight
			"Gala funds",
			"The expansion's \"cultural master\". It asks for: the 5 zone campaigns + Sojourner of Eversong Woods, Zul'Aman, Harandar and Voidstorm. Reward: Gala funds.",
		},
		[62111] = { -- Boots on the Ground: Arathi Basin
			"Win 10 matches with all 5 flags under control",
		},
		[62112] = { -- Boots on the Ground: Battle for Gilneas
			"Win 10 with the 3 flags",
