		[62116] = { -- Learning the Landscape: Silvershard Mines
			"Control 100 mine carts",
		},
		[62120] = { -- Altar of Blessings: The Penitent Troll
			"(unconfirmed) Puul and Oe: deduced because their blessings are missing in achievement 8.",
		},
		[62121] = { -- Altar of Blessings: Sacred Buffet Devotee
			"Bag carriers: mammoths with the <Repairer> tag, about 13 spawn points in the zone. They only give you the blessing if you talk to the one for your active blessing, without a mount.",
		},
		[62122] = { -- Tallest Tree in the Forest
			"Decor: Colossal Amani Stone Face",
			"15 rares · +50 reputation with the Amani Tribe each (weekly).",
		},
		[62125] = { -- Treasures of Zul'Aman
			"Toy: Pango Plating",
			"Each treasure gives +50 reputation with the Amani Tribe.",
			{ "Click the stash (inside the roots of a big tree) to accept the challenge.", 2437, 46.9, 81.9 },
			"At each urn, click it and kill the Chosen that appears:",
			{ "Akil'zon: Chosen of Akil'zon (going down the mountain south of the temple) · Eagle Talon", 2437, 51.6, 84.9 },
			{ "Nalorakk: Chosen of Nalorakk (below the entrance to the Den) · Bear Tooth", 2437, 32.7, 83.5 },
			{ "Halazzi: Chosen of Halazzi (clearing above the cave) · Lynx Claw", 2437, 34.5, 33.5 },
			{ "Jan'alai: Chosen of Jan'alai (burned tree south of the temple) · Dragonhawk Feather", 2437, 54.8, 22.4 },
			"Go back to the stash with all 4 and open it. If it doesn't open, you're missing one.",
		},
		[62126] = { -- Treasures of Voidstorm
			"Toy: Interdimensional Plot Sign",
			"13 treasures · each one gives +50 reputation with The Singularity.",
		},
		[62130] = { -- The Ultimate Predator
			"Decor: Open Domanaar Storage Crate",
			"14 rares · +50 reputation with The Singularity each (weekly). They can drop the Augmented Stormray and Sanguine Ripper mounts.",
		},
		[62133] = { -- Thrill of the Chase
			"Escape the Hungering Presence for at least 60 seconds. It is a giant ripper that chases anyone flying too high or too far off the map; it flies almost as fast as your skyriding mount and if it catches you, you die instantly.",
			"Start a stopwatch: /stopwatch.",
			"Climb to a high point at the edge of the map (the mountains between the Obscurion Citadel and Nexus-Point Xenas work).",
			"Fly toward the edge without spending skyriding charges. As soon as the warning \"You are being chased by [Hungering Presence]\" appears, start the stopwatch and run.",
			"Fly on a slight descent to keep Thrill of the Skies; use Skyward Ascent to regain height, Whirling Surge as an emergency boost and Second Wind to recharge.",
			"After 60 seconds you get the achievement; you can let it catch you now.",
			"Tip: pick the Whirling Surge talent in the skyriding tree before trying it.",
		},
		[62134] = { -- The Deadliest of Prey
			"5 hunts in War Mode",
