		[62186] = { -- The Party Must Go On
			"Decor: Eversong Party Tray",
			"It's done with the weekly quest Saltheril's Soiree: each week you invite one noble faction, so it takes at least 4 weeks.",
			"Tip: don't skip any week; if you miss one, the achievement is delayed another week.",
		},
		[62187] = { -- Grand Magister's Sommelier
			{ "It's done in the world quest Special Assignment: The Grand Magister's Drink. It shows up roughly every 28 days and lasts 6-7 days; the next one is expected around November 28 (estimate).", 2395, 41.6, 60.5 },
			"How the quest works: kill 10 grumpy vineyard bats, taste 3 wines with the NPCs and choose 1 with Razia. You only taste 3 of the 12 drinks per quest, so you need 4 quests (or 4 characters the same week, since it is account-wide).",
			"Before each round, open the achievement and pick 3 drinks you don't have yet.",
			"Talk to the NPCs before going to Razia: Heron's drink only shows up at Razia after talking to Heron.",
			"Special assignments unlock after doing 3 world quests in the zone.",
			"(unconfirmed) It probably does not count in a raid group (almost no world quest counts in raids since BfA); do it solo or in a 5-player group.",
			"(unconfirmed) Still to confirm: whether the 3 drinks you taste count or only the one you choose, and the NPC names.",
		},
		[62188] = { -- More Than Just Their Roots
			"Coordinates can vary a little (e.g. Kawayn 50.8 42.4). Chonon: 54.9 29.9.",
		},
		[62190] = { -- Life of the Party
			"Max reputation with the 4 subfactions of the Court: Blood Knights, Farstriders, Magisters, Shades of the Row · Mount: Umbral Dragonhawk",
