		[62196] = { -- Midnight Dungeoneer
			"The 8 dungeons are the launch ones (Altar of Fangs not included). Account-wide: you can do the healer and tank roles with other characters.",
		},
		[62199] = { -- Put a Pin in It
			"Find and join Chu'ke, the possessed doll. Criteria: Chu'ke found · Chu'ke joined.",
			{ "Find Chu'ke: on the tip of rock coming out of the sea to the right of Amani'Zar Village (a small island in the southeast corner of the map). Land on top, talk to it and pick the option about how this happened to it. It asks you for a button the size of an eye.", 2437, 59.24, 71.09 },
			{ "The button: fly to the Drybark Bluffs (north) and go into the little hut of Kalika, the tailoring trainer. Talk to her and ask for the button; she points you to a button on the floor, in the corner of the room (another report says it is behind a jade figurine to the right of the hut). Pick it up.", 2437, 38.66, 23.78 },
			"Join Chu'ke: go to the marked spot full of little dolls (also called Narak's Den), walk up to the big drum at the back and talk to Chu'ke. One report gives 37.80 90.11 (unconfirmed).",
			"The coordinates for steps 2 and 3 aren't confirmed yet; if they don't match, follow the game's markers.",
		},
		[62200] = { -- Gnome Alone
			"Gather the 6 writings of the lost gnome. No exact coordinates; these are the described locations, in story order:",
			"They don't have to be done in order.",
		},
		[62201] = { -- The Frog and the Princesses
			"Use /kiss on the 5 princess toads (have them targeted when you type it). Locations:",
			"These are community coordinates; if it isn't exact, look nearby.",
