		[62385] = { -- Staring Into The Void
			"Mount: Laboratory Stormray",
			"Unlock every option of the Voidstorm Research Console. Reward: Laboratory Stormray flying mount.",
			"You need renown 2 with The Singularity. The console and Void Researcher Anomander are on the Howling Ridge.",
			"Each of the 7 nodes costs 1 Untainted Void Sample; the weekly Research Console: Exploring the Void gives 1 per week (about 3 weeks in total).",
