		[63510] = { -- The Briny Best
			"1",
			"How it works (a player explained it on the Blizzard forums; the game doesn't say):",
			"Every fish in the fishing journal has a hidden score that reaches 100 when you reach Trophy rank.",
			"There are 28 fish with a score: the maximum is 2,800 and the achievement asks for 2,500, so you can skip about 3 fish.",
			"The 6 Cursed Oddities give no points: don't farm them for this.",
			"The score is warband-wide.",
			"The \"Rates\" text of each fish in the journal says where it shows up more (open water or pools), although all of them come both ways.",
			"Watch out for subzones with a single fish (for example the Vaults): they're easy to forget.",
			"What you fished before 12.1 doesn't count.",
		},
		[63512] = { -- Treasures of the Damned
			"Fish up the 10 artifacts of the fallen crew",
			"Fishing on the island brings up artifacts; each one starts a quest you turn in to Sluggs that gives 150 reputation with Tokka (only once per warband). Almost all of them need a certain rank with Tokka to show up.",
			"Tip: hand in each artifact as soon as it drops; the reputation ranks you up and unlocks the next ones.",
		},
		[63519] = { -- The Promise of Tomorrow
			"Title: Faithful to the Light",
			"Reward: title Faithful to the Light. Two stories, both given by Lor'themar Theron:",
			"Sins of the Past: 20 quests, starts with All Along the Watchtowers. It includes The Unbinding of Kith'ix (tied to the Kith'ix raid in 12.1.5).",
			"To the Faithful: 4 quests, starts with In Victory, Grief.",
		},
		[63520] = { -- Heroic: The Venomous Abyss
			"All 8 on Heroic",
		},
		[63521] = { -- The Venomous Abyss
			"The Venomous Abyss · S2 (Aug 19, 2026) · Serpentine Isle, inside the Vaults of Atal'Utek (through the Gate of the Serpent's Eye) · 8 · 292 to 302",
			"Bosses: Nek'zali the Soulcoiler · Entombed Sentinels · Vashnik the Malignant · The Lost Explorers · Sszorak · The Twin Fangs · The Coiled Altar · Ula'tek (final).",
			"Entrance: Serpentine Isle → Gate of the Serpent's Eye → Vaults of Atal'Utek → raid marker. Raid Finder: item level 276, 4 wings (Aug 19 to Sep 9).",
			"Mythic: Ula'tek (account-wide): Title: End of Venom",
			"Well, Well, Little Sky: Nek'zali",
			"Buy Fly Balm from the Forgotten Assistant (the skeleton next to the raid entrance).",
			"Before Nek'zali, use it next to Kupamanduka at the venom fountain. Right-click the frog and carry it to the boss room.",
			"When the fight starts, the frog hops around the room. Get close, aim the blue kick arrow at the soulcoil well in the center and kick it in. Bring several helpers.",
			"Check that it counted and kill Nek'zali.",
			"Is Venom Stasis A Joke To You?: Entombed Sentinels",
			"Each sentinel (Breath of Ula'tek and Blood of Ula'tek) must heal more than half of its health with Vitriolic Stasis in the same fight.",
			"Split them. Bring Breath down until it has more than 50 points less than Blood. In the intermission, let it heal before solving the pairs of Helical Toxins.",
			"Repeat the other way around: bring Blood down and let it heal.",
			"When both criteria count, bring both down evenly and kill them. Keep a margin above 50%.",
			"Accidental Inclusion: The Lost Explorers",
			"Before opening the coffin that starts the fight, one player picks up the special fish from the nearby platform.",
			"Hoji appears, invulnerable, and fights with you. Kill the 3 expeditioners, Hoji included.",
			"Kept You Waiting Huh?: Vashnik",
			"You have to gather one slime of each color (orange, red and purple) to create the solidified serpent venom, kill it and then kill Vashnik.",
			"Put Vashnik between the orange and red fountains. Kill the oranges and split the big red. Bring a small red to the purple fountain and control it (banish, stun); kill the rest.",
			"On the next Imbibe, put the boss between purple and orange. Join an orange with the saved red just as a purple arrives. Release the 3 controls at the same time.",
			"Kill the solidified venom, confirm and kill Vashnik.",
			"Bring grips, knockbacks and good crowd control.",
			"Jumping Through Hoops: Sszorak",
			"Before starting, interact with the small incense to the left of the gate, at the top of the stairs down to the arena. Without it the hoops don't appear.",
			"On each wind push (Crosswinds), assign players to the 3 hoops and aim their path to go through them. Repeat on each series. Don't move to the next phase until the series is complete.",
			"Taking a Bite out of Slime: The Twin Fangs",
			"Four different players each pick up a slime and give it to Ithraz during the Voracious Feast, in this order:",
			"Crunchy Appetizer: small island in the venom pond, to the right of the room after the expeditioners",
			"Sumptuous Soup: Hole in the floor on the left, after Nek'zali's room",
			"Tasty Glob: Green fountain on the right, at the top of the stairs before Vashnik",
			"Wobbly Dessert: Ledge on the right, inside The Twin Fangs' room",
			"Each carrier goes into the feast on their turn; the others wait outside. The follower appearance lasts 1 hour: if it runs out, go back for the slime.",
			"Watch Out Behind You: The Coiled Altar",
			"Free the players controlled by Dread March to create Dread Manifestations (ghosts). Tanks aim Sever Soul away from them.",
			"A player with Unsettling Fixation turns around to move their ghost and faces it to stop it. Keep them away from the edge.",
			"In the last phase, hold damage and let enough Dread March through so everyone has a ghost. Check the raid frames and kill the boss.",
			"The ghosts may not survive the phase change. With more than 20 players there are ghost-limit issues: a small raid is better.",
			"Don't resurrect someone right before the end without checking that they also have the fixate.",
			"No Egg Scramble: Ula'tek",
			"Go down the drum on the left, top left of the arena, to the egg; walking over it picks it up. Watch out for the sea of venom.",
			"The carrier has about 20 seconds before the egg falls into a circle; the next one catches it right away. Rotate, because there is a debuff that prevents picking it up again.",
			"Caustic Waves can knock it down early: have a backup ready. If nobody catches it, you have to retry.",
			"Assign 4 or 5 carriers and a healer near them. Reward: Ula'took pet.",
			"Comforting Da Spirits",
			"It doesn't count toward Glory. It can be done with the raid already cleared (after killing the bosses).",
			"Take the Ancient Amani Mask from the left alcove of the crypt, before the expeditioners. Activate it to enter the Ancestral Vision. If you die, put it on again.",
			"Talon-Sworn Ra'ven: Lower left alcove of the expeditioners' room",
			"Farmer Su'mekaya: Small island in the venom pond, to the right of the room after the expeditioners",
			"B'faloh: The same small island as Su'mekaya",
			"Stonecarver Babooi'jin: On the left right after Sszorak, before the blood sacrifice area",
			"Hexweaver Vola'ni: Turn around after taking the mask in the crypt",
			"Chef Momo'jin: Right as you enter the corridor toward the Entombed Sentinels",
			"Trapper Haka'li: Left alcove before the big staircase toward Vashnik",
			"Shieldbearer Kora'man: At the start of the Sentinels' wing, turn right and follow the venom wall to the alcove of The Twin Fangs",
			"Scout Jino'ka: In the venom pit after Nek'zali. Leave her for last: it's dangerous",
			"Some spots can cost you a death: bring someone who can resurrect you.",
		},
