		[63631] = { -- Captain Tokka's Crew
			"Max rank with Tokka (it's under Reputation)",
			"Bloodsworn Crew rank with Captain Tokka",
			"It is a reputation with ranks, not renown.",
			"Strange: 0",
			"Doomed Sailor: 100",
			"Cursed Angler: 2700",
			"Venom Angler: 5300",
			"Bloodsworn Crew: 8400",
			{ "How to start: finish the Serpentine Isle campaign (Original Sin). Captain Tokka is in the main camp and gives Venom Fishing: the proof is in the slime, which opens the chain. The chain leaves you at Doomed Sailor.", 2512, 57.21, 48.63 },
			{ "Dailies from Second Officer Sluggs or Brinedrinker Gills: (unconfirmed) · Tokka's Madness", 2512, 51.62, 49.84 },
			"World quest Open Sea Fishing: 500 · Usually northeast of the island; it shows up roughly every week",
			"10 quest items you fish up (once per warband): 150 each · The same ones as Treasures of the Damned: see Professions",
			{ "Rewards (vendor: Second Officer Sluggs):", 2512, 51.64, 49.83 },
			"Doomed Sailor: Housing decor and the Brakpuffer Platter recipe",
			"Cursed Angler: Coiled Stardevourer lure recipe and profession recipes (150 Moxie)",
			"Venom Angler: Feast of Knowledge and Tokka's Multiward recipes, decor; Venom Elemental pet (100 gold)",
			"Bloodsworn Crew: The Coiled Huntress fishing pole (6000 Marl). With Coiled Filament (fished with that pole on the island): Sea Isle Serpent mount (2500), Poisoned Ripper transmog weapon (1000) and others (500)",
			"Do the dailies every day; with that and the weekly world quest you get there in a few weeks.",
			"Fishing up the 10 items gives you 1500 at once, plus the Treasures of the Damned achievement.",
			"The mount comes after the achievement: first the fishing pole, then gather 2500 Filament.",
		},
		[63632] = { -- Toxic Trophies
			"Trophy rank with 8 fish",
			"Trophy rank (5 of 5) with the 8 fish marked \"Yes\" in the table above. The ranks are Guppy → Minnow → Pike → Shark → Trophy and they go up by fishing more of that fish; it's estimated at about 100 of each, but it varies (one player got Trophy with the Muddy Fish in just a few catches).",
			"The 3 common ones (Deathfish, Darter, Tlhapi) go up on their own while you fish the rest.",
			"Do the Serpent Head and the Stardevourer together in the Vaults.",
			"For the Swarmcaller, follow the Curse Waves and go straight to the Cursed Waters as soon as one ends.",
		},
		[63633] = { -- A Stack of Snacks
			"Pet: Claqui",
			"Give Claqui (Ki'clak) 5 snacks with the world quest Claqui's Binge (Serpentine Isle). Pet: Claqui. Account-wide.",
			{ "Unlock: talk to Olawu, do Ghosts of the Ring (Tokka's Landing) and finish Don't be Afrayed.", 2512, 58.5, 47.2 },
			"When the quest is up (outside a raid group): kill the marked ghosts until you have 10 Swirling Ectoplasm (69.6 56.4), talk to Mab'jul and pick the snack option. Give it to Claqui (69.3 52.1).",
			"Buying snacks from the vendor doesn't count. You need 5 quests (several weeks).",
		},
		[63634] = { -- Where Did You Get That?
